import sys

sys.setrecursionlimit(1000000)

class TVar:
    __slots__ = ("id", "link")

    def __init__(self, id_):
        self.id = id_
        self.link = None


class TCon:
    __slots__ = ("name", "args")

    def __init__(self, name, args):
        self.name = name
        self.args = tuple(args)


class TArrow:
    __slots__ = ("left", "right")

    def __init__(self, left, right):
        self.left = left
        self.right = right


class TTup:
    __slots__ = ("left", "right")

    def __init__(self, left, right):
        self.left = left
        self.right = right


class Scheme:
    __slots__ = ("vars", "type")

    def __init__(self, vars, type_):
        self.vars = vars
        self.type = type_


class ParseError(Exception):
    pass


class TypeError_(Exception):
    pass


class NameError_(Exception):
    pass


_RESERVED = frozenset({"fun", "let", "rec", "in", "if", "then", "else", "true", "false"})

EOF = 0
INT = 1
NAME = 2
KW = 3
OP = 4
LP = 5
RP = 6
LB = 7
RB = 8
COMMA = 9

_APP = 5
_MUL = 4
_ADD = 3
_CONS = 2
_EQ = 1

_OP = {
    "=": _EQ,
    "<": _EQ,
    "::": _CONS,
    "+": _ADD,
    "-": _ADD,
    "*": _MUL,
}
_RIGHT_ASSOC = {"::"}

def _is_ascii_lower(c):
    return "a" <= c <= "z"

def _is_ascii_upper(c):
    return "A" <= c <= "Z"

def _is_ascii_alpha(c):
    return _is_ascii_lower(c) or _is_ascii_upper(c)

def _is_ascii_digit(c):
    return "0" <= c <= "9"

def _is_name_start(c):
    return _is_ascii_lower(c) or c == "_"

def _is_name_cont(c):
    return _is_ascii_alpha(c) or _is_ascii_digit(c) or c in ("_", "'")

def _tokenize(src):
    toks = []
    n = len(src)
    i = 0
    while i < n:
        c = src[i]

        if c.isspace():
            i += 1
            continue

        if _is_ascii_digit(c):
            j = i + 1
            while j < n and _is_ascii_digit(src[j]):
                j += 1
            toks.append((INT, int(src[i:j])))
            i = j
            continue

        if _is_name_start(c):
            j = i + 1
            while j < n and _is_name_cont(src[j]):
                j += 1
            word = src[i:j]
            if word in _RESERVED:
                toks.append((KW, word))
            else:
                toks.append((NAME, word))
            i = j
            continue

        if c == "-":
            if i + 1 < n and src[i + 1] == ">":
                toks.append((OP, "->"))
                i += 2
            else:
                toks.append((OP, "-"))
                i += 1
            continue

        if c == ":":
            if i + 1 < n and src[i + 1] == ":":
                toks.append((OP, "::"))
                i += 2
            else:
                raise ParseError()
            continue

        if c in "(),+*=<":
            toks.append((OP, c))
            i += 1
            continue

        if c == "[":
            if i + 1 < n and src[i + 1] == "]":
                toks.append((LB, "["))
                toks.append((RB, "]"))
                i += 2
                continue
            raise ParseError()

        if c == "]":
            raise ParseError()

        raise ParseError()

    toks.append((EOF, None))
    return toks


class Parser:
    def __init__(self, toks):
        self.toks = toks
        self.pos = 0

    def peek(self):
        return self.toks[self.pos]

    def kind(self):
        return self.toks[self.pos][0]

    def value(self):
        return self.toks[self.pos][1]

    def at(self, kind, value=None):
        t = self.toks[self.pos]
        return t[0] == kind and (value is None or t[1] == value)

    def eat(self, kind, value=None):
        if not self.at(kind, value):
            raise ParseError()
        self.pos += 1

    def start_atom(self, tok=None):
        if tok is None:
            tok = self.peek()
        k = tok[0]
        return k == INT or k == NAME or k == LP or k == LB or (k == KW and tok[1] in ("true", "false"))

    def parse_expression(self, allow_form=True):
        if allow_form:
            k = self.kind()
            if k == KW:
                v = self.value()
                if v == "fun":
                    return self.parse_fun()
                if v == "let":
                    return self.parse_let()
                if v == "if":
                    return self.parse_if()
        return self.parse_binary_noform(_EQ)

    def parse_binary_noform(self, min_prec):
        left = self.parse_atom_noform()

        while True:
            tok = self.peek()
            k = tok[0]

            if k == EOF:
                break

            if k == OP:
                op = tok[1]
                if op == "->" or op == "=" and False:
                    break

            if self.start_atom(tok) and _APP >= min_prec:
                right = self.parse_binary_noform(_APP + 1)
                if left[0] == "App":
                    left = ("App", left[1], left[2] + [right])
                else:
                    left = ("App", left, [right])
                continue

            if k == OP:
                op = tok[1]
                prec = _OP.get(op)
                if prec is None or prec < min_prec:
                    break

                self.pos += 1
                if op in _RIGHT_ASSOC:
                    right = self.parse_binary_noform(prec)
                else:
                    right = self.parse_binary_noform(prec + 1)

                if op == "::":
                    if right[0] == "Cons":
                        left = ("Cons", [left] + right[1])
                    else:
                        left = ("Cons", [left, right])
                else:
                    if left[0] == "LeftOp" and left[1] == op:
                        left = ("LeftOp", op, left[2] + [right])
                    else:
                        left = ("LeftOp", op, [left, right])
                continue

            break

        return left

    def parse_atom_noform(self):
        tok = self.peek()
        k = tok[0]

        if k == INT:
            self.pos += 1
            return ("Int", tok[1])

        if k == NAME:
            self.pos += 1
            return ("Var", tok[1])

        if k == KW:
            v = tok[1]
            if v == "true" or v == "false":
                self.pos += 1
                return ("Bool", v == "true")
            raise ParseError()

        if k == LP:
            self.pos += 1
            first = self.parse_expression(True)

            if self.at(OP, ","):
                self.pos += 1
                second = self.parse_expression(True)
                self.eat(RP)
                return ("Tuple", first, second)

            self.eat(RP)
            return first

        if k == LB:
            self.pos += 1
            self.eat(RB)
            return ("Nil",)

        raise ParseError()

    def parse_fun(self):
        self.eat(KW, "fun")
        args = []

        while self.kind() == NAME:
            args.append(self.value())
            self.pos += 1
            if self.kind() != NAME:
                break

        if not args:
            raise ParseError()

        self.eat(OP, "->")
        body = self.parse_expression(True)
        return ("Fun", args, body)

    def parse_let(self):
        self.eat(KW, "let")
        is_rec = False

        if self.at(KW, "rec"):
            is_rec = True
            self.pos += 1

        if self.kind() != NAME:
            raise ParseError()
        name = self.value()
        self.pos += 1

        if is_rec:
            args = []
            while self.kind() == NAME:
                args.append(self.value())
                self.pos += 1
                if self.kind() != NAME:
                    break
            if not args:
                raise ParseError()
            self.eat(OP, "=")
            rhs = self.parse_expression(True)
            self.eat(KW, "in")
            body = self.parse_expression(True)
            return ("LetRec", name, args, rhs, body)

        args = []
        while self.kind() == NAME:
            args.append(self.value())
            self.pos += 1
            if self.kind() != NAME:
                break

        if args:
            self.eat(OP, "=")
            rhs_body = self.parse_expression(True)
            rhs = ("Fun", args, rhs_body)
        else:
            self.eat(OP, "=")
            rhs = self.parse_expression(True)

        self.eat(KW, "in")
        body = self.parse_expression(True)
        return ("Let", name, rhs, body)

    def parse_if(self):
        self.eat(KW, "if")
        cond = self.parse_expression(False)
        self.eat(KW, "then")
        e1 = self.parse_expression(True)
        self.eat(KW, "else")
        e2 = self.parse_expression(True)
        return ("If", cond, e1, e2)


class TypeInferrer:
    def __init__(self):
        self.var_id = 0
        self.int_type = TCon("int", ())
        self.bool_type = TCon("bool", ())
        self.list_con = "list"
        self.env = self.initial_env()

    def initial_env(self):
        env = {}

        a = self.fresh_var()
        b = self.fresh_var()
        env["fst"] = Scheme(frozenset((a.id, b.id)), TArrow(TTup(a, b), a))

        a = self.fresh_var()
        b = self.fresh_var()
        env["snd"] = Scheme(frozenset((a.id, b.id)), TArrow(TTup(a, b), b))

        a = self.fresh_var()
        env["hd"] = Scheme(frozenset((a.id,)), TArrow(TCon("list", (a,)), a))

        a = self.fresh_var()
        env["tl"] = Scheme(frozenset((a.id,)), TArrow(TCon("list", (a,)), TCon("list", (a,))))

        a = self.fresh_var()
        env["null"] = Scheme(frozenset((a.id,)), TArrow(TCon("list", (a,)), self.bool_type))

        return env

    def fresh_var(self):
        self.var_id += 1
        return TVar(self.var_id)

    def repr(self, t):
        if not isinstance(t, TVar):
            return t

        path = []
        cur = t
        while isinstance(cur, TVar) and cur.link is not None:
            path.append(cur)
            cur = cur.link

        for v in path:
            v.link = cur
        return cur

    def copy_type(self, t, subst):
        if not subst:
            return self.repr(t)

        r = self.repr(t)

        if isinstance(r, TVar):
            if r.id in subst:
                return self.fresh_var()
            return r

        if isinstance(r, TArrow):
            return TArrow(self.copy_type(r.left, subst), self.copy_type(r.right, subst))

        if isinstance(r, TTup):
            return TTup(self.copy_type(r.left, subst), self.copy_type(r.right, subst))

        if isinstance(r, TCon):
            return TCon(r.name, tuple(self.copy_type(x, subst) for x in r.args))

        return r

    def instantiate(self, scheme):
        if not scheme.vars:
            return self.repr(scheme.type)

        subst = {x: None for x in scheme.vars}
        for x in scheme.vars:
            subst[x] = self.fresh_var()
        return self.copy_type(scheme.type, subst)

    def occurs(self, var_id, t):
        stack = [t]
        seen = set()

        while stack:
            t = self.repr(stack.pop())

            if isinstance(t, TVar):
                if t.id == var_id:
                    return True
                if t.id in seen:
                    continue
                seen.add(t.id)
                continue

            if id(t) in seen:
                continue
            seen.add(id(t))

            if isinstance(t, TArrow):
                stack.append(t.left)
                stack.append(t.right)
            elif isinstance(t, TTup):
                stack.append(t.left)
                stack.append(t.right)
            elif isinstance(t, TCon):
                for x in t.args:
                    stack.append(x)

        return False

    def unify(self, a, b):
        stack = [(a, b)]

        while stack:
            a, b = stack.pop()
            a = self.repr(a)
            b = self.repr(b)

            if a is b:
                continue

            if isinstance(a, TVar) and isinstance(b, TVar):
                if a.id != b.id:
                    a.link = b
                continue

            if isinstance(a, TVar):
                if self.occurs(a.id, b):
                    raise TypeError_()
                a.link = b
                continue

            if isinstance(b, TVar):
                if self.occurs(b.id, a):
                    raise TypeError_()
                b.link = a
                continue

            if isinstance(a, TArrow) and isinstance(b, TArrow):
                stack.append((a.left, b.left))
                stack.append((a.right, b.right))
                continue

            if isinstance(a, TTup) and isinstance(b, TTup):
                stack.append((a.left, b.left))
                stack.append((a.right, b.right))
                continue

            if isinstance(a, TCon) and isinstance(b, TCon) and a.name == b.name and len(a.args) == len(b.args):
                for x, y in zip(a.args, b.args):
                    stack.append((x, y))
                continue

            raise TypeError_()

    def collect_free(self, t, block=None):
        result = set()
        stack = [t]
        seen = set()

        while stack:
            t = self.repr(stack.pop())

            if isinstance(t, TVar):
                if block is not None and t.id in block:
                    continue
                result.add(t.id)
                continue

            if id(t) in seen:
                continue
            seen.add(id(t))

            if isinstance(t, TArrow):
                stack.append(t.left)
                stack.append(t.right)
            elif isinstance(t, TTup):
                stack.append(t.left)
                stack.append(t.right)
            elif isinstance(t, TCon):
                for x in t.args:
                    stack.append(x)

        return result

    def env_free(self, env):
        result = set()

        for scheme in env.values():
            free = self.collect_free(scheme.type, scheme.vars)
            result |= free

        return result

    def generalize(self, env, t):
        free = self.collect_free(t)
        env_free = self.env_free(env)
        quantified = frozenset(free - env_free)
        return Scheme(quantified, t)

    def lookup(self, env, name):
        try:
            return env[name]
        except KeyError:
            raise NameError_()

    def infer(self, node, env):
        kind = node[0]

        if kind == "Int":
            return self.int_type

        if kind == "Bool":
            return self.bool_type

        if kind == "Nil":
            return TCon("list", (self.fresh_var(),))

        if kind == "Var":
            scheme = self.lookup(env, node[1])
            return self.instantiate(scheme)

        if kind == "Fun":
            _, args, body = node
            child = dict(env)
            vars_ = []
            for x in args:
                v = self.fresh_var()
                vars_.append(v)
                child[x] = Scheme(frozenset(), v)
            body_type = self.infer(body, child)
            t = body_type
            for v in reversed(vars_):
                t = TArrow(v, t)
            return t

        if kind == "Tuple":
            _, a, b = node
            return TTup(self.infer(a, env), self.infer(b, env))

        if kind == "Cons":
            _, operands = node
            n = len(operands)

            elem = None
            tail_type = None

            for i, operand in enumerate(operands):
                t = self.infer(operand, env)

                if i == n - 1:
                    if elem is None:
                        elem = self.fresh_var()
                    tail_type = TCon("list", (elem,))
                    self.unify(t, tail_type)
                else:
                    if elem is None:
                        elem = t
                    else:
                        self.unify(elem, t)

            if elem is None:
                elem = self.fresh_var()
            if tail_type is None:
                tail_type = TCon("list", (elem,))

            return tail_type

        if kind == "LeftOp":
            _, op, operands = node
            result = self.infer(operands[0], env)

            if op in ("+", "-", "*"):
                self.unify(result, self.int_type)
                for operand in operands[1:]:
                    self.unify(self.infer(operand, env), self.int_type)
                return self.int_type

            if op == "<":
                self.unify(result, self.int_type)
                for operand in operands[1:]:
                    self.unify(self.infer(operand, env), self.int_type)
                return self.bool_type

            if op == "=":
                for operand in operands[1:]:
                    self.unify(result, self.infer(operand, env))
                    result = self.bool_type
                return result

            raise TypeError_()

        if kind == "App":
            _, func, args = node
            result = self.infer(func, env)

            for arg in args:
                arg_type = self.infer(arg, env)
                out = self.fresh_var()
                self.unify(result, TArrow(arg_type, out))
                result = out

            return result

        if kind == "If":
            _, cond, e1, e2 = node
            self.unify(self.infer(cond, env), self.bool_type)
            t1 = self.infer(e1, env)
            t2 = self.infer(e2, env)
            self.unify(t1, t2)
            return t1

        if kind == "Let":
            _, name, rhs, body = node
            rhs_type = self.infer(rhs, env)
            scheme = self.generalize(env, rhs_type)
            child = dict(env)
            child[name] = scheme
            return self.infer(body, child)

        if kind == "LetRec":
            _, name, args, rhs, body = node
            rec_var = self.fresh_var()

            child = dict(env)
            child[name] = Scheme(frozenset(), rec_var)

            vars_ = []
            for x in args:
                v = self.fresh_var()
                vars_.append(v)
                child[x] = Scheme(frozenset(), v)

            rhs_type = self.infer(rhs, child)

            fun_type = rhs_type
            for v in reversed(vars_):
                fun_type = TArrow(v, fun_type)

            self.unify(rec_var, fun_type)

            scheme = self.generalize(env, rec_var)
            child = dict(env)
            child[name] = scheme
            return self.infer(body, child)

        raise TypeError_()

    def rename(self, t):
        names = {}
        counter = 0

        def next_name():
            nonlocal counter
            i = counter
            counter += 1
            first = chr(ord("a") + (i % 26))
            suffix = "" if i < 26 else str(i // 26)
            return "'" + first + suffix

        stack = []
        seen_ids = set()
        mapping = {}

        def collect(t):
            stack.append((t, False))

        collect(t)

        while stack:
            t, done = stack.pop()
            t = self.repr(t)

            if isinstance(t, TVar):
                if t.id in mapping:
                    continue
                mapping[t.id] = next_name()
                continue

            if isinstance(t, TArrow):
                stack.append((t.right, True))
                stack.append((t.left, False))
                continue

            if isinstance(t, TTup):
                stack.append((t.right, False))
                stack.append((t.left, False))
                continue

            if isinstance(t, TCon):
                for x in t.args:
                    stack.append((x, False))
                continue

        return mapping

    def precedence(self, t):
        t = self.repr(t)
        if isinstance(t, TArrow):
            return 1
        if isinstance(t, TTup):
            return 2
        return 3

    def need_paren_for_arrow_left(self, t):
        return isinstance(self.repr(t), TArrow)

    def need_paren_for_tup_operand(self, t):
        r = self.repr(t)
        return isinstance(r, (TArrow, TTup))

    def need_paren_for_list_operand(self, t):
        r = self.repr(t)
        return isinstance(r, (TArrow, TTup))

    def format_type(self, t, mapping):
        out = []
        stack = [(t, 0)]

        while stack:
            t, mode = stack.pop()
            t = self.repr(t)

            if isinstance(t, TVar):
                out.append(mapping[t.id])
                continue

            if isinstance(t, TCon):
                if t.name in ("int", "bool"):
                    out.append(t.name)
                elif t.name == "list":
                    if self.need_paren_for_list_operand(t.args[0]):
                        out.append("(")
                    stack.append((t.args[0], 0))
                    out.append(") list")
                    continue
                else:
                    raise TypeError_()

            elif isinstance(t, TArrow):
                if self.need_paren_for_arrow_left(t.left):
                    out.append("(")
                stack.append((t.left, 0))
                out.append(") -> ")
                stack.append((t.right, 0))
                continue

            elif isinstance(t, TTup):
                if self.need_paren_for_tup_operand(t.left):
                    out.append("(")
                stack.append((t.left, 0))
                out.append(") * ")

                if self.need_paren_for_tup_operand(t.right):
                    out.append("(")
                stack.append((t.right, 0))
                if self.need_paren_for_tup_operand(t.right):
                    out.append(")")

                continue

            raise TypeError_()

        return "".join(out)


def infer(src: str) -> str:
    try:
        toks = _tokenize(src)
        parser = Parser(toks)
        ast = parser.parse_expression(True)

        if parser.kind() != EOF:
            raise ParseError()

    except ParseError:
        raise SyntaxError()

    inf = TypeInferrer()

    try:
        t = inf.infer(ast, inf.env)
    except NameError_:
        raise NameError()
    except TypeError_:
        raise TypeError()

    mapping = inf.rename(t)
    return inf.format_type(t, mapping)
